//! Файл: settings/catalog/dex_event.rs
//! Что делает: настройки перечитывания пула по событию (задача t144, живой случай SHOPINX 16.11.2026): решение 313 —
//! замер перечитывания и счётчик потерянных событий пулов (раздел «Система», вся система). Отдельный файл: каталоги
//! base.rs и dex.rs — общие для многих задач. Решение 314 — класс очереди узла для перечитываний по событию (раздел
//! «DEX», область «площадка», только площадка DEX — .dex_venue()); решение 315 — пул V3 одним обращением к узлу при
//! перечитывании по событию (там же). Все необязательные, значений нет.
//! Кто вызывает: settings/catalog/mod.rs.
//! От чего зависит: settings/catalog/mod.rs (короткая запись d и наборы областей).
//! Настройки: это и есть их список (зеркало docs/SETTINGS.md, разделы «Система» и «DEX»).

use super::{G, V, d};
use crate::settings::schema::{Kind as K, Limit as L, SettingDef};

/// Настройки решений 313–315. Порядок — как в docs/SETTINGS.md.
#[rustfmt::skip]
pub static DEX_EVENT: &[SettingDef] = &[
    d("Система", "log.pool_refresh_timing", K::Bool, L::None, "да/нет", G, "Решение 313 (включаемое, для разбора): замер перечитывания пула ПО СОБЫТИЮ (полоса цены вышла за прочитанные слова карты тиков — off_map; событие требует перечитать пул — refresh) — запись журнала dex.pool_refresh на каждое такое перечитывание: DEX, пул, причина, блок события и блок чтения, общее время, каждое обращение к узлу BSC отдельно (ожидание в очереди темпа узла / сам запрос, вызовов в нём), класс очереди узла, слов карты тиков, сколько сообщений ждало в канале сессии пачки к концу, итог. Нет или не задана — замера нет (одно чтение настройки на перечитывание). Необязательна").optional(),
    d("Система", "log.pool_events_lost_interval_s", K::Integer, L::Positive, "секунды", G, "Решение 313: событие пула (MarketEvent::Pool) не ушло ядру, потому что канал событий ядра полон (отправка без ожидания, чтобы медленное ядро не задерживало чтение событий; раньше терялось молча). Каждая потеря считается; запись журнала dex.pool_events_lost (Warn) с числом потерь с прошлой записи — не чаще раза в столько секунд (первая — сразу). Не задана — записей нет, отправка как раньше. Необязательна").optional(),
    d("DEX", "dex.event_refresh_urgency", K::Choice, L::None, "класс", V, "Решение 314: класс очереди узла BSC (срочность, gateway/urgency.rs: trade → check → quote → background, строгий порядок с долей фона bsc.node_background_share_pct) для перечитываний пула, вызванных событием пула в сессии слушателя: полоса цены вышла за карту тиков (off_map), событие требует перечитать пул (реорг, расхождение), бины на блоке события, одна перечитка пар многомонетного пула, пары общего контракта WooFi по логу. Класс действует только на время этого чтения — остальная работа сессии остаётся фоновой. trade — наравне с путём сделки (расчёт кандидата, предпроверка, исполнение — по приходу внутри класса); check — после пути сделки, наравне с проверками монет; quote — наравне с котировками живого экрана. Не задана — как раньше: класс сессии не задан (background)").choices(&["trade", "check", "quote", "background"]).dex_venue().optional(),
    d("DEX", "dex.event_refresh_one_call", K::Bool, L::None, "да/нет", V, "Решение 315: перечитывание пула V3 (ABI PancakeSwap V3 / Uniswap V3) по событию (полоса цены вышла за карту тиков — off_map; событие требует перечитать пул) ОДНИМ обращением к узлу: slot0, liquidity, [swapFee фабрики — решение 274], [fee() пула — решение 281] и слова карты TickLens одним eth_call к Multicall3 (dex.multicall3) на блоке чтения; слова — вокруг тика записи после события, настоящий диапазон проверяется по slot0 того же ответа (внутри — лишние слова отбрасываются, иначе второе обращение за словами того же блока). Итог тот же, что у последовательного чтения на этом блоке (не меньше трёх обращений). Работает только при заданном dex.multicall3. Нет или не задана — как раньше").dex_venue().optional(),
];
